<?php
$e = static fn($value): string => htmlspecialchars((string) $value, ENT_QUOTES, 'UTF-8');
$activeJokis = $db->query("SELECT id, nama, whatsapp, keahlian FROM joki WHERE status = 'aktif' ORDER BY nama")->fetchAll();
?>
