.allocation-intro{margin-bottom:20px}.allocation-intro p{margin:7px 0 0;color:var(--muted)}.allocation-card{margin-bottom:16px}.allocation-card .panel-head{align-items:flex-start}.allocation-meta{display:flex;flex-wrap:wrap;gap:8px;margin-top:7px;color:var(--muted);font-size:12px}.allocation-meta span{display:inline-flex;align-items:center;gap:5px}.allocation-select{min-width:190px;padding:10px 12px;border:1px solid var(--line);border-radius:8px;background:#fff;color:var(--ink);font:inherit}.allocation-table td{vertical-align:middle}.allocation-table td:first-child strong{font-family:'Space Grotesk',sans-serif}.allocation-table .btn{white-space:nowrap}@media(max-width:700px){.allocation-table{min-width:760px}}
