<?php foreach ($allocationOrders as $order): ?><tr><td><strong><?= $e($order['order_code']) ?></strong><small><?= $e($order['customer_name']) ?></small></td><td><?= $e($order['service_title']) ?><small><?= $e($order['category_name']) ?></small></td><td><?= $order['deadline_at'] ? date('d M Y, H:i', strtotime($order['deadline_at'])) : '-' ?></td><td><strong><?= formatRupiah($order['total_price']) ?></strong><small>Bagian joki <?= formatRupiah(floor($order['total_price'] * .70)) ?></small></td><td><form id="alokasi-<?= (int) $order['id'] ?>" method="post" action="proses_alokasi.php"><input type="hidden" name="action" value="allocate"><input type="hidden" name="csrf" value="<?= $e(adminCsrf()) ?>"><input type="hidden" name="order_id" value="<?= (int) $order['id'] ?>"><select class="allocation-select" name="joki_id" required><option value="">Pilih joki aktif</option><?php foreach ($activeJokis as $joki): ?><option value="<?= (int) $joki['id'] ?>"><?= $e($joki['nama']) ?> · <?= $e($joki['keahlian']) ?></option><?php endforeach; ?></select></form></td><td><button class="btn small" form="alokasi-<?= (int) $order['id'] ?>"><i class="fa-solid fa-share"></i> Alokasikan</button></td></tr><?php endforeach; ?>
<?php if (!$allocationOrders): ?><tr><td colspan="6" class="empty"><i class="fa-solid fa-circle-check"></i> Semua order aktif sudah memiliki joki.</td></tr><?php endif; ?></tbody></table></div></div>
