<?php foreach ($assignedOrders as $order): ?><tr><td><strong><?= $e($order['order_code']) ?></strong><small><?= $e($order['customer_name']) ?></small></td><td><?= $e($order['service_title']) ?><small><?= $e($order['category_name']) ?></small></td><td><?= $order['deadline_at'] ? date('d M Y, H:i', strtotime($order['deadline_at'])) : '-' ?></td><td><strong><?= $e($order['joki_name']) ?></strong><small>Diproses joki</small></td><td><form id="ganti-<?= (int) $order['id'] ?>" method="post" action="proses_alokasi.php"><input type="hidden" name="action" value="replace"><input type="hidden" name="csrf" value="<?= $e(adminCsrf()) ?>"><input type="hidden" name="order_id" value="<?= (int) $order['id'] ?>"><select class="allocation-select" name="joki_id" required><option value="">Pilih pengganti</option><?php foreach ($activeJokis as $joki): ?><?php if ((int) $joki['id'] !== (int) $order['joki_id']): ?><option value="<?= (int) $joki['id'] ?>"><?= $e($joki['nama']) ?> · <?= $e($joki['keahlian']) ?></option><?php endif; ?><?php endforeach; ?></select></form></td><td><button class="btn small" form="ganti-<?= (int) $order['id'] ?>"><i class="fa-solid fa-arrows-rotate"></i> Ganti</button></td></tr><?php endforeach; ?>
